export type TrainingEraId = (typeof trainingEras)[number]['id'];

export type TrainingCategory =
  | 'optimization'
  | 'regularization'
  | 'architecture'
  | 'systems'
  | 'self-supervision'
  | 'adaptation'
  | 'alignment'
  | 'data-selection';

